from taf.ul.vdu.helm.session import OneClickSession


class OneClickConnection(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, ip, port, username="", password="", secure=False, verify=False):
        self._one_click_session = OneClickSession(ip, port, username="", password="", secure=secure, verify=verify)

    def _to_endpoint(self, method, url, **content):
        response = self._one_click_session.send_request(method=method,
                                                        endpoint=url,
                                                        **content)
        return response

    def get_filtered_ne_info(self, filter_value=''):
        url = '/get_filtered_ne_info'
        body = {'filter_value': filter_value}

        response = self._to_endpoint(method='post',
                                     url=url,
                                     data=body
                                     )
        return response

    def new_ne(self, **kwargs):
        url = '/new_ne'
        body = kwargs

        response = self._to_endpoint(method='post',
                                     url=url,
                                     data=body)

        return response

    def delete_ne(self, ne_name):
        url = '/delete'
        body = {'ne_name': ne_name}

        response = self._to_endpoint(method='post',
                                     url=url,
                                     data=body
                                     )
        return response

    def ne_deploy(self, ne_name, build_version):
        url = '/ne_deploy'
        body = {'ne_name': ne_name, 'ne_target_version': build_version}

        response = self._to_endpoint(method='post',
                                     url=url,
                                     data=body
                                     )
        return response

    def ne_undeploy(self, ne_name):
        url = '/ne_undeploy'
        body = {'ne_name': ne_name}

        response = self._to_endpoint(method='post',
                                     url=url,
                                     data=body
                                     )
        return response
